<?php use Dilemma\Views; ?>
<?php if (!$list['items']): ?><div class="empty-state"><p><?= $t($empty) ?></p></div><?php else: ?><div class="debate-list"><?php foreach ($list['items'] as $item): ?>
<article class="debate-row"><div class="debate-category"><?= $e($item['topic']) ?></div><div class="debate-title"><h3><a href="/debate/<?= $e($item['id']) ?>"><?= $e($item['title']) ?></a></h3><p><?= $e(implode(' ↔ ', array_map(static fn ($p) => $p['account_status'] === 'deleted' ? Dilemma\I18n::t('deleted_participant') : $p['alias'], $item['participants']))) ?></p></div><div class="debate-meta"><span class="status status-<?= $e($item['status']) ?>"><?= $t($item['status'] === 'open' ? 'looking_for_opponent' : $item['status']) ?></span><span><?= (int) ceil((int) $item['message_count'] / 2) ?> <?= $t('rounds') ?></span><time datetime="<?= $e($item['updated_at']) ?>Z"><?= $e(substr($item['updated_at'], 0, 10)) ?></time></div><a class="row-arrow" href="/debate/<?= $e($item['id']) ?>" aria-label="<?= $e($item['title']) ?>">↗</a></article>
<?php endforeach; ?></div><?= Views::pagination($list['page'], $list['pages']) ?><?php endif; ?>
